package com.amz.statusly;
import android.graphics.Bitmap;import android.graphics.BitmapFactory;import android.os.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.io.*;import java.util.*;
public class PhotoCompressActivity extends AppCompatActivity{String path;ImageView close,compress;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_video_compress);path=getIntent().getStringExtra("path");close=findViewById(R.id.closeBtn);compress=findViewById(R.id.compress);((ImageView)findViewById(R.id.withoutWater)).setVisibility(View.GONE);close.setOnClickListener(v->finish());compress.setOnClickListener(v->save());}
void save(){try{Bitmap b=BitmapFactory.decodeFile(path);File d=new File(getCacheDir(),"Output");d.mkdirs();File f=new File(d,UUID.randomUUID()+".jpg");FileOutputStream o=new FileOutputStream(f);b.compress(Bitmap.CompressFormat.JPEG,100,o);o.close();Toast.makeText(this,"Photo compressed successfully",Toast.LENGTH_SHORT).show();}catch(Exception e){new AlertDialog.Builder(this).setTitle("Compression failed").setMessage(e.toString()).setPositiveButton("OK",null).show();}}}
